content.query:
let ConsentGrants = AuditLogs
| where TimeGenerated {TimeRange}
| where OperationName == 'Consent to application'
| extend AppName = tostring(TargetResources[0].displayName)
| extend User = tostring(InitiatedBy.user.userPrincipalName)
| project TimeGenerated, User, AppName, OperationName;
let DeviceCodeSignins = SigninLogs
| where TimeGenerated {TimeRange}
| where AuthenticationProtocol == 'deviceCode'
| project TimeGenerated, User = UserPrincipalName, AppName = AppDisplayName, OperationName = 'Device Code Sign-in';
let AiTMIndicators = SigninLogs
| where TimeGenerated {TimeRange}
| where ResultType == 0
| where AuthenticationRequirement == 'multiFactorAuthentication'
| project TimeGenerated, User = UserPrincipalName, AppName = AppDisplayName, OperationName = 'MFA Sign-in (AiTM Check)';
union ConsentGrants, DeviceCodeSignins, AiTMIndicators
| order by TimeGenerated desc

let StorageOps = AzureActivity
| where TimeGenerated {TimeRange}
| where OperationNameValue has 'Microsoft.Storage'
| where OperationNameValue has 'listKeys'
| project TimeGenerated, Source = 'Storage Key Listing', Caller, CallerIpAddress, Detail = OperationNameValue;
let KVOps = AzureDiagnostics
| where TimeGenerated {TimeRange}
| where ResourceProvider == 'MICROSOFT.KEYVAULT'
| where OperationName in ('SecretGet', 'SecretList', 'KeyGet')
| project TimeGenerated, Source = 'Key Vault Access', Caller = identity_claim_upn_s, CallerIpAddress = CallerIPAddress, Detail = OperationName;
union StorageOps, KVOps
| order by TimeGenerated desc
